# 008_bpm_orologio_assoluto.py
#
# I BPM CON L'EXPANDER: la musica non perde piu' il tempo che il computer le ruba.
#
# LA CAUSA VERA, trovata dopo aver provato tre rimedi sbagliati.
# La posizione nel brano si costruiva SOMMANDO gli intervalli fra un giro e
# l'altro del ciclo di riproduzione:
#
#     accumulated_ticks += delta_time * speed * ticks_per_second
#     if delta_time > 0.05: delta_time = 0.05    # e questo tagliava
#
# Cosi' ogni millesimo che il computer si prendeva spariva per sempre, e gli
# errori si sommavano. Misurato sul PC del cliente: in 27 secondi reali la
# musica ne suonava 11,8 - quindici secondi di brano evaporati.
#
# COSA CAMBIA. Si tiene un ANCORAGGIO (un istante reale + la posizione musicale
# che gli corrisponde) e la posizione si RICALCOLA da li' a ogni giro, invece di
# sommarla. Se il computer si blocca un secondo, al risveglio la posizione e'
# gia' quella giusta: non c'e' niente da recuperare perche' non si e' perso
# niente. E' come lavorano i sequencer veri - orologio monotono e posizione
# derivata, mai sommata.
#
# ⛔ I TRE RIMEDI SBAGLIATI, per non riprovarli:
#   1. tagliare a 50 ms (com'era): la musica restava indietro per sempre;
#   2. rincorrere suonando piu' veloce: "prima rallenta un attimo e poi va su di
#      giri". Abbassare la percentuale non toglie il difetto, lo allunga
#      soltanto - provato al 25%, all'8% e al 2%;
#   3. alleggerire una funzione della GUI alla volta: sono infinite, e infatti
#      dopo la ricerca il problema si spostava sui preferiti.
# Nessuno dei tre toglieva la causa, che era l'orologio a somme.
#
# ⚠️ COSA NON SI ROMPE (provato, non dedotto):
#     10 s regolari      vecchio 10,00   nuovo 10,00
#     27 s con blocchi   vecchio 11,82   nuovo 26,82   <- il difetto
#     con 5 s di pausa   vecchio  6,00   nuovo  6,00   <- la pausa non conta
#     velocita' x2       vecchio  9,00   nuovo  8,99
# L'ancoraggio si rifa' nei tre casi che altrimenti sballerebbero il conto: la
# ripresa dopo una pausa, il cambio di velocita' e il cambio di tempo del brano
# (set_tempo). Lo spostamento nel brano non serve: fa stop e riparte da capo.
#
# ⚠️ Resta anche il riallineamento: se un giro tarda oltre 120 ms, le note NUOVE
# di quel frammento non si suonano (gli spegnimenti e i controlli passano tutti,
# se no restano note accese sull'expander). Serve a non sparare in un colpo le
# note arretrate, che con l'expander vorrebbe dire intasarlo.
#
# Va insieme alla 005 (la ricerca) e alla 009 (i preferiti), che tolgono i
# blocchi alla radice. Questa fa in modo che, quando un blocco capita lo stesso,
# non costi musica.
#
# ⛔ Punto di ripristino: tag RESTORE_pre_timing_midi_20260904_1154

CODICE = 'def _playback_loop(self):\n    """Loop di riproduzione MIDI con timing ad alta precisione.\n    ZERO CALLBACK dal thread audio — nessuna interazione con Tkinter/GIL.\n    Su Windows usa timeBeginPeriod(1) per risoluzione timer 1ms reale.\n    Tutti gli attributi sono pre-cached come variabili locali per velocità."""\n    \n    # ✅ WINDOWS: attiva risoluzione timer 1ms (default è 15.6ms!)\n    _winmm = None\n    if sys.platform == \'win32\':\n        try:\n            import ctypes\n            _winmm = ctypes.windll.winmm\n            _winmm.timeBeginPeriod(1)\n        except:\n            _winmm = None\n        # ✅ Alza priorità thread audio\n        try:\n            import ctypes\n            handle = ctypes.windll.kernel32.GetCurrentThread()\n            ctypes.windll.kernel32.SetThreadPriority(handle, 2)  # THREAD_PRIORITY_HIGHEST\n        except:\n            pass\n    \n    try:\n        events = self._events\n        num_events = len(events)\n        event_index = 0\n        \n        # ✅ RICOSTRUISCI STATO per seek: processa setup senza suonare note\n        if self.current_tick > 0:\n            self._rebuild_state_at_tick(self.current_tick)\n        \n        # Trova primo evento >= current_tick\n        start_tick = self.current_tick\n        while event_index < num_events and events[event_index][0] < start_tick:\n            event_index += 1\n        \n        # ✅ Pre-cache TUTTO come locals (evita attribute lookup nel hot loop)\n        _synth = self.synth\n        _sfid = self.sfid\n        _stop = self._stop_event\n        _perf = time.perf_counter\n        _sleep = time.sleep\n        _tpb = self.ticks_per_beat\n        _channel_muted = self.channel_muted\n        _channel_volumes = self.channel_volumes\n        _channel_pan = self.channel_pan\n        _channel_expression = self.channel_expression\n        _channel_sustain = self.channel_sustain\n        _channel_reverb_send = self.channel_reverb_send\n        _channel_chorus_send = self.channel_chorus_send\n        _channel_bank_msb = self.channel_bank_msb\n        _channel_bank_lsb = self.channel_bank_lsb\n        _channel_programs = self.channel_programs\n        _active_notes = self.active_notes\n        _channel_dirty = self._channel_dirty  # ✅ Flag per UI polling\n        \n        # Synth methods pre-cached\n        _noteon = _synth.noteon\n        _noteoff = _synth.noteoff\n        _cc = _synth.cc\n        _pitch_bend = _synth.pitch_bend\n        _program_select = _synth.program_select\n\n        # 🎛️ Rimappa strumenti: carico dal DB alla prima riproduzione (se il\n        # Mixer non l\'ha gia\' impostata) e la pre-cache per il hot loop.\n        if not self._instrmap_loaded:\n            try:\n                self.instrument_map = FluidSynthPlayer.load_instrument_remap()\n            except Exception:\n                pass\n            self._instrmap_loaded = True\n        _instr_map = self.instrument_map\n\n        # 🕵️ SPIA DEL TIMING. Scrive nel log di KaraDom (log/karadom_debug.log,\n        #    quello che il cliente sa gia\' inviare dal menu) quanto resta\n        #    indietro questo thread mentre suona. Serve a misurare DENTRO il\n        #    programma vero: i ritardi qui dipendono da Tk, dai 35 thread e\n        #    dalla porta MIDI, cose che su un banco di prova non si\n        #    riproducono - e infatti una cura tarata li\' ha peggiorato.\n        #    Se il log non e\' attivo (avvio normale) non si raccoglie niente\n        #    e non costa niente.\n        try:\n            from .debug_logger import DEBUG as _spia, dbg as _dbg\n        except Exception:\n            _spia, _dbg = False, None\n        _sp_n = _sp_sopra = _sp_sopra_tot = 0\n        _sp_max = _sp_max_tot = 0.0\n        _sp_somma = _sp_persi = _sp_persi_tot = 0.0\n        _sp_inizio = _sp_quando = _perf()\n\n        last_time = _perf()\n        accumulated_ticks = float(start_tick)\n        # L\'OROLOGIO E\' ASSOLUTO, NON A SOMME (4 set 2026).\n        # Prima la posizione si costruiva sommando gli intervalli fra un\n        # giro e l\'altro: ogni millesimo perso o tagliato spariva per\n        # sempre e gli errori si accumulavano. Adesso si tiene un\n        # ANCORAGGIO - un istante reale e la posizione musicale che gli\n        # corrisponde - e la posizione si RICALCOLA da li\' a ogni giro.\n        # Se il computer si blocca un secondo, al risveglio la posizione e\'\n        # gia\' quella giusta: non c\'e\' niente da recuperare perche\' non si\n        # e\' perso niente. E\' come lavorano i sequencer veri: orologio\n        # monotono e posizione derivata, mai sommata.\n        _anc_reale = _perf()\n        _anc_tick = accumulated_ticks\n        _anc_speed = 1.0\n        _anc_tempo = None\n        # il tempo che il taglio dei 50 ms farebbe sparire,\n        # da restituire poco per volta\n        # oltre questo ritardo non si rincorre: ci si riallinea saltando\n        # le note di quel frammento (vedi il commento piu\' sotto)\n        _SOGLIA_SALTO = 0.12\n\n        current_tempo = self._get_tempo_at_tick(start_tick)\n        speed = self._speed\n        pitch_offset = self._pitch_semitones  # ✅ Offset utente in semitoni\n        \n        while not _stop.is_set() and event_index < num_events:\n            \n            # Gestisci pausa (low-frequency check)\n            if self.is_paused:\n                while self.is_paused and not _stop.is_set():\n                    _sleep(0.01)\n                last_time = _perf()\n                speed = self._speed  # Re-read dopo pausa\n                pitch_offset = self._pitch_semitones  # Re-read pitch dopo pausa\n                # si riparte da dove ci si era fermati: l\'ancoraggio va\n                # rifatto, se no il tempo passato in pausa conterebbe come\n                # musica e il brano salterebbe avanti\n                _anc_reale = last_time\n                _anc_tick = accumulated_ticks\n                continue\n            \n            if _stop.is_set():\n                break\n            \n            # ✅ Timing ad alta precisione\n            now = _perf()\n            delta_time = now - last_time\n            last_time = now\n            \n            # ✅ Re-read pitch offset (trasposizione nota)\n            new_pitch = self._pitch_semitones\n            if new_pitch != pitch_offset:\n                for _ch in range(16):\n                    _cc(_ch, 123, 0)      # All Notes Off\n                    _pitch_bend(_ch, 8192) # Reset pitch bend\n                pitch_offset = new_pitch\n                print(f"🎵 MIDI transpose: {pitch_offset:+d} semitoni")\n            \n            if _spia:\n                _sp_n += 1\n                _r = delta_time * 1000.0\n                _sp_somma += _r\n                if _r > _sp_max:\n                    _sp_max = _r\n                if delta_time > 0.05:\n                    _sp_sopra += 1\n                    _sp_persi += _r - 50.0     # musica che il taglio fa sparire\n                if now - _sp_quando >= 5.0:\n                    # una riga solo se in questi 5 secondi si e\' perso tempo:\n                    # se e\' filato liscio il log non si sporca\n                    if _sp_sopra:\n                        _dbg("MIDI-TIMING",\n                             "expander=%s  cicli=%d  ritardo medio=%.1f ms  "\n                             "max=%.0f ms  oltre 50ms=%d  musica persa=%.0f ms" % (\n                                 "si" if getattr(self, "is_expander", False) else "no",\n                                 _sp_n, _sp_somma / max(1, _sp_n), _sp_max,\n                                 _sp_sopra, _sp_persi))\n                    _sp_sopra_tot += _sp_sopra\n                    _sp_persi_tot += _sp_persi\n                    if _sp_max > _sp_max_tot:\n                        _sp_max_tot = _sp_max\n                    _sp_n = _sp_sopra = 0\n                    _sp_max = 0.0\n                    _sp_somma = _sp_persi = 0.0\n                    _sp_quando = now\n\n            # ✅ DOPO UN BLOCCO SI RIALLINEA, NON SI RINCORRE (4 set 2026)\n            #\n            # Tre modi di reagire a un giro che tarda, e li abbiamo provati\n            # tutti e tre sul campo:\n            #\n            #   1. TAGLIARE (com\'era): oltre 50 ms il tempo in piu\' si\n            #      buttava via. La musica non rincorreva, ma restava\n            #      indietro per sempre: misurato il 52% del dovuto, cioe\'\n            #      meta\' velocita\', e 5,2 secondi di brano spariti in 42.\n            #\n            #   2. RINCORRERE suonando piu\' veloce (il "debito"): il tempo\n            #      tornava giusto, ma si SENTIVA - "prima rallenta un attimo\n            #      e poi va su di giri". Al 25% era evidente, e abbassare la\n            #      percentuale non toglie il difetto: lo allunga e basta,\n            #      perche\' l\'ondulazione resta.\n            #\n            #   3. RIALLINEARSI di colpo (questo): la posizione salta al\n            #      tempo vero e si riparte in orario. Le note di quel\n            #      frammento non si suonano - c\'e\' un micro-buco al posto\n            #      della rincorsa - ma il tempo non ondula mai.\n            #\n            # Per un karaoke il terzo e\' il migliore: chi canta segue il\n            # tempo, e un buco di due decimi si perdona; una base che\n            # accelera no.\n            #\n            # ⚠️ Gli eventi saltati NON si ignorano: si processano lo stesso\n            #    (piu\' sotto, con `_salta_note`), altrimenti restano note\n            #    accese senza il loro spegnimento e l\'expander suona\n            #    all\'infinito. Si eseguono note_off, cambi di suono e\n            #    controlli; si saltano solo le note DA ACCENDERE.\n            _salta_note = False\n            if delta_time > _SOGLIA_SALTO:\n                _salta_note = True\n\n            # Converti in ticks usando il tempo corrente + speed\n            ticks_per_second = (_tpb * 1000000.0) / current_tempo\n            # se velocita\' o tempo del brano sono cambiati, l\'ancoraggio\n            # non vale piu\': si riparte dalla posizione attuale\n            if speed != _anc_speed or current_tempo != _anc_tempo:\n                _anc_tick = accumulated_ticks\n                _anc_reale = now\n                _anc_speed = speed\n                _anc_tempo = current_tempo\n            # la posizione si RICALCOLA dall\'orologio, non si somma:\n            # quello che il computer perde non sparisce piu\'\n            accumulated_ticks = _anc_tick + (now - _anc_reale) * speed * ticks_per_second\n            \n            cur_tick = int(accumulated_ticks)\n            self.current_tick = cur_tick\n            \n            # ✅ PROCESS EVENTI — hot loop inlined, zero callback\n            while event_index < num_events:\n                ev_tick, ev_track, msg = events[event_index]\n                if ev_tick > cur_tick:\n                    break\n                event_index += 1\n                \n                msg_type = msg.type\n                \n                if msg_type == \'note_on\':\n                    ch = msg.channel\n                    if _channel_muted[ch]:\n                        continue\n                    vel = msg.velocity\n                    # durante il riallineamento le note NUOVE non si\n                    # suonano: sono quelle del frammento saltato. Gli\n                    # spegnimenti (vel == 0) passano lo stesso, se no\n                    # resterebbero note accese sull\'expander.\n                    if _salta_note and vel > 0:\n                        continue\n                    note = msg.note\n                    # ✅ Trasposizione nota (skip ch 9 = percussioni)\n                    if ch != 9 and pitch_offset != 0:\n                        note = max(0, min(127, note + pitch_offset))\n                    if vel > 0:\n                        _noteon(ch, note, vel)\n                        _active_notes[ch] += 1\n                        _channel_dirty[ch] = True  # ✅ Flag per UI, non callback\n                    else:\n                        _noteoff(ch, note)\n                        n = _active_notes[ch] - 1\n                        _active_notes[ch] = n if n > 0 else 0\n                \n                elif msg_type == \'note_off\':\n                    ch = msg.channel\n                    if _channel_muted[ch]:\n                        continue\n                    note = msg.note\n                    # ✅ Trasposizione nota (skip ch 9 = percussioni)\n                    if ch != 9 and pitch_offset != 0:\n                        note = max(0, min(127, note + pitch_offset))\n                    _noteoff(ch, note)\n                    n = _active_notes[ch] - 1\n                    _active_notes[ch] = n if n > 0 else 0\n                \n                elif msg_type == \'control_change\':\n                    ch = msg.channel\n                    cc_num = msg.control\n                    val = msg.value\n                    if cc_num == 0:\n                        _channel_bank_msb[ch] = val\n                    elif cc_num == 32:\n                        _channel_bank_lsb[ch] = val\n                    elif cc_num == 7:\n                        _channel_volumes[ch] = val\n                        if not _channel_muted[ch]:\n                            _cc(ch, 7, val)\n                    elif cc_num == 10:\n                        _channel_pan[ch] = val\n                        _cc(ch, 10, val)\n                    elif cc_num == 11:\n                        _channel_expression[ch] = val\n                        if not _channel_muted[ch]:\n                            _cc(ch, 11, val)\n                    elif cc_num == 64:\n                        _channel_sustain[ch] = val\n                        _cc(ch, 64, val)\n                    elif cc_num == 91:\n                        _channel_reverb_send[ch] = val\n                        _cc(ch, 91, val)\n                    elif cc_num == 93:\n                        _channel_chorus_send[ch] = val\n                        _cc(ch, 93, val)\n                    elif cc_num == 121:\n                        _cc(ch, 121, 0)\n                        _channel_expression[ch] = 127\n                        _channel_sustain[ch] = 0\n                        if not _channel_muted[ch]:\n                            _cc(ch, 7, _channel_volumes[ch])\n                            _cc(ch, 11, 127)\n                        _cc(ch, 10, _channel_pan[ch])\n                    else:\n                        _cc(ch, cc_num, val)\n                \n                elif msg_type == \'program_change\':\n                    if _sfid is not None:\n                        ch = msg.channel\n                        bank = _channel_bank_msb[ch]\n                        if ch == 9:\n                            bank = 128\n                        prog = msg.program\n                        # 🎛️ sostituzione strumento di default (rimappa globale)\n                        if _instr_map:\n                            _r = _instr_map.get((ch == 9, prog, bank))\n                            if _r is not None:\n                                prog, bank = _r\n                        _program_select(ch, _sfid, bank, prog)\n                        _channel_programs[ch] = prog\n                \n                elif msg_type == \'set_tempo\':\n                    current_tempo = msg.tempo\n                    self.tempo = current_tempo\n                \n                elif msg_type == \'pitchwheel\':\n                    # ✅ Pitchwheel dal file: passa diretto (range default 2 semitoni)\n                    # La trasposizione è gestita via note transpose, non pitch bend\n                    bend = int(8192 + msg.pitch)\n                    bend = max(0, min(16383, bend))\n                    _pitch_bend(msg.channel, bend)\n                \n                elif msg_type == \'sysex\':\n                    self._process_sysex(msg)\n                \n                elif msg_type == \'aftertouch\':\n                    try:\n                        _synth.channel_pressure(msg.channel, msg.value)\n                    except:\n                        pass\n                \n                elif msg_type == \'polytouch\':\n                    try:\n                        _synth.key_pressure(msg.channel, msg.note, msg.value)\n                    except:\n                        pass\n            \n            # ✅ Re-read speed e pitch (potrebbero cambiare da UI)\n            speed = self._speed\n            pitch_offset = self._pitch_semitones\n            \n            # ✅ Sleep adattivo fino al prossimo evento\n            if event_index < num_events:\n                next_tick = events[event_index][0]\n                ticks_remaining = next_tick - accumulated_ticks\n                if ticks_remaining > 0 and ticks_per_second > 0:\n                    sleep_time = ticks_remaining / ticks_per_second\n                    if speed > 0:\n                        sleep_time /= speed\n                    # Cap a max 3ms, dormi 80% del tempo calcolato\n                    sleep_time = min(sleep_time * 0.8, 0.003)\n                    if sleep_time > 0.0005:\n                        _sleep(sleep_time)\n                else:\n                    _sleep(0.001)\n            else:\n                _sleep(0.001)\n        \n        # Fine riproduzione\n        if not _stop.is_set():\n            self.is_playing = False\n            self._all_notes_off()\n            print("🎵 Riproduzione MIDI terminata")\n            \n            if self.on_playback_end:\n                try:\n                    self.on_playback_end()\n                except:\n                    pass\n                    \n    except Exception as e:\n        print(f"❌ Errore playback: {e}")\n        import traceback\n        traceback.print_exc()\n    finally:\n        if _spia and _dbg is not None:\n            try:\n                _durata = _perf() - _sp_inizio\n                _sp_sopra_tot += _sp_sopra\n                _sp_persi_tot += _sp_persi\n                if _sp_max > _sp_max_tot:\n                    _sp_max_tot = _sp_max\n                _dbg("MIDI-TIMING",\n                     "RIEPILOGO brano: durata %.0f s, expander=%s, "\n                     "ritardi oltre 50ms: %d, ritardo peggiore %.0f ms, "\n                     "musica persa in tutto %.0f ms (%.1f%% del brano)" % (\n                         _durata,\n                         "si" if getattr(self, "is_expander", False) else "no",\n                         _sp_sopra_tot, _sp_max_tot, _sp_persi_tot,\n                         (_sp_persi_tot / 10.0 / _durata) if _durata > 0 else 0.0))\n            except Exception:\n                pass\n        # ✅ WINDOWS: ripristina risoluzione timer default\n        if _winmm:\n            try:\n                _winmm.timeEndPeriod(1)\n            except:\n                pass\n\n'


def apply():
    import moduli.fluidsynth_player as fp
    P = getattr(fp, "FluidSynthPlayer", None)
    if P is None or not hasattr(P, "_playback_loop"):
        print("patch 008: motore MIDI diverso, salto")
        return False
    # il ciclo si compila NELLO SPAZIO DEI NOMI del modulo: dentro usa decine di
    # nomi globali suoi (time, sys, ctypes, le costanti) che qui non ci sono
    spazio = fp.__dict__
    exec(compile(CODICE, "<patch008>", "exec"), spazio)
    P._playback_loop = spazio["_playback_loop"]
    print("patch 008: orologio assoluto, la musica non perde piu' il tempo")
    return True


try:
    apply()
except Exception as _e:
    print("patch 008: %s" % _e)
